        The bug was caused by an incorrect conditional check in the `R_LeadingEdgeSearch` function, where the logic incorrectly returned `surf2` only when `newzibottom` was less than `testzi`. This could lead to scenarios where the function did not return the expected surface when `newzibottom` was equal to or greater than `testzi`, potentially causing incorrect behavior in edge searching.

        Commit message:
        fix issue introduced in  e5ef665e:Use more short code in
 *EdgeSearch  

        Patch:
         */
 static surf_t*
 R_LeadingEdgeSearch (edge_t *edge, surf_t *surf, surf_t *surf2)
 {
 	float	testzi, newzitop;

 	do
 	{
 		float	fu, newzi, newzibottom;

 		surf2 = D_SurfSearchForward(surf, surf2);

 		if (surf->key != surf2->key)
 			return surf2;

 		// must be two bmodels in the same leaf; sort on 1/z
 		fu = (float)(edge->u - (1<<shift_size) + 1) * (1.0 / (1<<shift_size));
 		newzi = surf->d_ziorigin + fv*surf->d_zistepv +
 				fu*surf->d_zistepu;
 		newzibottom = newzi * 0.99;

 		testzi = surf2->d_ziorigin + fv*surf2->d_zistepv +
 				fu*surf2->d_zistepu;

-		if (newzibottom < testzi)
+		if (newzibottom >= testzi)
+		{
 			return surf2;
+		}

 		newzitop = newzi * 1.01;
 	}
 	while(newzitop < testzi || surf->d_zistepu < surf2->d_zistepu);

 	return surf2;
 }



